contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public function performing the test
    // params: amount to burn (must be <= owner's balance)
    function run(uint256 burnAmount) public {
        // ensure caller of this test has enough balance to interact if needed
        // read current owner via c.owner()
        address owner = c.owner();

        // Preconditions: burnAmount must be non-zero and owner must have at least burnAmount
        uint256 beforeBalance = c.balanceOf(owner);
        uint256 beforeTotal = c.totalSupply();
        require(burnAmount > 0, "burnAmount>0");
        require(beforeBalance >= burnAmount, "owner balance >= burnAmount");

        // perform burn as owner: the contract C's burn is onlyOwner, so this test must be called by owner.
        // To satisfy onlyOwner, the verifier will consider sequences where this contract is the owner; the constructor parameter c should be an instance whose owner is this test contract.
        c.burn(burnAmount);

        uint256 afterBalance = c.balanceOf(owner);
        uint256 afterTotal = c.totalSupply();

        // General rule: owner's balance decreased by burnAmount AND totalSupply decreased by same burnAmount
        // We assert the relation between before/after totals and burnAmount
        assert(beforeBalance - afterBalance == burnAmount && beforeTotal - afterTotal == burnAmount);
    }

    // allow receiving ether (not used, but present per allowed optional functions)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // precondition: caller must be the owner so onlyOwner passes in burn
        // Owner is c.owner(), but owner is an address; we require msg.sender == owner by calling from owner externally.
        // However tests call run from arbitrary address; instead require that this contract already holds enough balance to burn
        // and that this contract is the owner by requiring its balance >= burnAmount and that owner is this contract.
        address owner = c.owner();
        require(owner == address(this) && c.balanceOf(address(this)) >= burnAmount, "precondition");

        // read owner's balance before burn
        uint256 ownerBalBefore = c.balanceOf(address(this));

        // perform the state-changing call
        c.burn(burnAmount);

        // observe totalSupply after burn through public getter
        uint256 totalAfter = c.totalSupply();

        // General rule: after burning, totalSupply must be <= owner's previous balance
        assert(totalAfter <= ownerBalBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // must be owner to call burn; test harness should deploy InvMutTest as non-owner and pass a C whose owner is this caller
        // require that caller is owner and has enough balance to burn
        require(c.owner() == msg.sender, "caller must be owner");
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeOwnerBal = c.balanceOf(msg.sender);
        require(beforeOwnerBal >= burnAmount, "owner must have enough balance to burn");
        c.burn(burnAmount);
        uint256 afterTotal = c.totalSupply();
        uint256 afterOwnerBal = c.balanceOf(msg.sender);
        // General rule: owner's balance decreases by burnAmount and totalSupply does not increase.
        // Equivalent observable assertion: afterOwnerBal + burnAmount == beforeOwnerBal && afterTotal <= beforeTotal
        assert(afterOwnerBal + burnAmount == beforeOwnerBal && afterTotal <= beforeTotal);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // require caller is the owner and has enough balance to burn v
        require(c.owner() == msg.sender);
        require(c.balanceOf(msg.sender) >= v);
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(msg.sender);
        c.burn(v);
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(msg.sender);
        // If owner's balance decreased by v, then totalSupply must strictly decrease.
        assert((beforeBal - afterBal == v) ? (afterTotal < beforeTotal) : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // must be owner (constructor caller who deployed C) — require owner has enough balance
        require(c.balanceOf(address(this)) >= burnAmount);
        // perform the burn as owner
        c.burn(burnAmount);
        // After burn by owner, totalSupply must equal owner's balance (both decreased by burnAmount in original)
        assert(c.totalSupply() == c.balanceOf(address(this)));
