pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, 0, 0); }

    // fuzzed: amount to burn and initial supply assigned to owner
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        // keep values in wide admissible domain but avoid trivial zero-initialization overflow issues
        initialSupply = bound(initialSupply, 1, type(uint256).max / 2);
        // bound burnAmount so it can be within [0, initialSupply] allowing both no-op and real burns
        burnAmount = bound(burnAmount, 0, initialSupply);

        // deploy a fresh contract with given initialSupply and set msg.sender as owner
        // Note: setUp deployed a contract with (0,0,0); redeploy here to use fuzzed initialSupply
        c = new C(initialSupply, "T", "T");

        // record totalSupply before burn
        uint256 before = c.totalSupply();

        // owner (this test contract) calls burn
        // the contract's constructor set owner = msg.sender where msg.sender was this contract at creation,
        // so we are already the owner and can call burn directly.
        // Perform burn; wrap in try/catch to observe success but burn is expected to succeed when balance sufficient
        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If burn succeeded, the invariant of the reference contract is: totalSupply == before - burnAmount
        // If burn reverted (shouldn't for admissible inputs where owner has enough balance), we still assert the
        // universal property using the contract's public getter: when call succeeded, totalSupply decreased by amount.
        if (ok) {
            // exactly one assertion reading c's public surface
            assertTrue(c.totalSupply() == before - burnAmount);
        } else {
            // If the call reverted, the reference contract would also revert for insufficient balance.
            // For completeness, assert that totalSupply remains unchanged when burn reverted.
            assertTrue(c.totalSupply() == before);
        }
    }
}

