pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }

    // fuzz: who burns and how much
    function testFuzz_property(address burner, uint256 mintAmount) public {
        // keep burner non-zero to be a distinct actor and avoid minting to address(0)
        vm.assume(burner != address(0));
        // bound mintAmount to a reasonable range so arithmetic in contract stays simple
        mintAmount = bound(mintAmount, 1, type(uint128).max);

        // owner is the test contract deployer (address(this) during setUp), which is owner of c
        // mint tokens to the burner, then have owner burn some (we will burn from owner, so first mint to owner)
        // To exercise burn by owner, mint some to owner and then burn a chosen amount.

        // mint tokens to the owner (address(this)) so burn can be invoked by owner
        // We use the public mintToken which is onlyOwner, and address(this) is owner.
        c.mintToken(address(this), mintAmount);

        // record totalSupply before burn
        uint256 before = c.totalSupply();

        // choose a burn amount in [1, mintAmount]
        uint256 burnAmount = bound(mintAmount, 1, mintAmount);

        // call burn as owner (address(this) is owner by construction)
        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: burn(amount) called by the owner succeeds (ok == true) and the
        // contract's totalSupply decreases by exactly amount. The mutant omits decreasing totalSupply.
        // We assert the universal property that if burn returned/finished OK then totalSupply == before - burnAmount.
        if (ok) {
            assertTrue(c.totalSupply() == before - burnAmount);
        } else {
            // If the call reverted (should not for valid inputs), the reference also would revert; still assert that
            // totalSupply did not change (burn didn't complete)
            assertTrue(c.totalSupply() == before);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function containing the test logic
    // Params:
    // - initialSupply: must be >= 1 to give owner a positive balance
    // - burnAmount: amount to burn (should be <= initialSupply)
    function run(uint256 initialSupply, uint256 burnAmount) public {
        // Preconditions for meaningful test
        require(initialSupply > 0, "initialSupply must be > 0");
        require(burnAmount <= initialSupply, "burnAmount must be <= initialSupply");

        // Use constructor parameters of existing contract c by calling no constructor here.
        // We first record the current totalSupply and owner balance via public getters.
        uint256 beforeTotal = c.totalSupply();
        address owner = c.owner();
        uint256 ownerBalanceBefore = c.balanceOf(owner);

        // Ensure the recorded state is consistent with inputs: if the provided initialSupply
        // does not match the current contract state, the test is not applicable.
        // This prevents accidental false positives on unrelated deployments.
        require(beforeTotal == initialSupply * (10 ** uint256(c.decimals())), "mismatched initialSupply vs contract state");
        require(ownerBalanceBefore >= burnAmount, "owner has insufficient balance to burn the requested amount");

        // Execute the mutation-sensitive call: owner calls burn through this test contract.
        // The contract C restricts burn to onlyOwner; this test contract must be the owner to succeed.
        // Therefore, require that this test runner is the owner.
        require(msg.sender == owner, "test runner must be the owner of c");

        // Perform the burn (state-changing call must be top-level)
        c.burn(burnAmount);

        // Observe totalSupply after burn
        uint256 afterTotal = c.totalSupply();

        // General rule: totalSupply decreased by exactly burnAmount
        assert(afterTotal + burnAmount == beforeTotal);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // precondition: the caller must be the owner and must have at least v balance
        // We cannot directly ensure msg.sender is owner here, so require that this contract
        // currently holds enough balance to burn v by first checking c.balanceOf(address(this)) >= v
        // but balanceOf is public mapping getter on C: balanceOf(address) -> uint256
        require(c.balanceOf(address(this)) >= v, "Insufficient balance for burn");
        // perform the state-changing call
        c.burn(v);
        // After a correct burn, totalSupply should have the same parity as before minus v (i.e.,
        // totalSupply_before - v). For original contract this means totalSupply_before - v == totalSupply_after.
        // A simple invariant we can observe via public getters: (totalSupply_before - totalSupply_after) == v
        // But that exact equality was stated as already tried. Instead assert that totalSupply does not become zero
        // unless v equals the previous totalSupply. This is violated by the mutant which can double-decrement and
        // force zero when v != previous totalSupply.
        uint256 after = c.totalSupply();
        // read totalSupply before by adding back v (assuming correct single decrement): before = after + v
        // So assert that either after != 0 or v == after + v (i.e., previous totalSupply was v).
        assert(after != 0 || (v == after + v));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
