        require(c.balanceOf(msg.sender) >= v, "caller must have enough balance");
        // record totalSupply before
        uint256 before = c.totalSupply();
        // perform the burn which should reduce totalSupply by exactly v in the original
        c.burn(v);
        uint256 after = c.totalSupply();
        // assert that totalSupply decreased by exactly v
        assert(after + v == before);
    }
