}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // require that msg.sender is the owner by using the deployed contract's owner
        // we cannot change msg.sender here, so require that the test caller is the owner
        // The caller of run must be the owner of c for onlyOwner to succeed
        // Check that caller has enough balance to burn v
        require(c.owner() == msg.sender, "caller must be owner");
        require(c.balanceOf(msg.sender) >= v, "owner must have enough balance");
        uint256 before = c.totalSupply();
        c.burn(v);
        uint256 afterTs = c.totalSupply();
        // Assert that totalSupply decreased by exactly v
        assert(before - afterTs == v);
    }
