contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // precondition: msg.sender must be the owner to pass onlyOwner in burn
        // and owner must have at least v to satisfy the require in burn
        // We observe owner via c.owner() and balance via c.balanceOf(owner)
        address owner = c.owner();
        uint256 before = c.totalSupply();
        uint256 ownerBalanceBefore = c.balanceOf(owner);
        require(ownerBalanceBefore >= v, "owner needs enough balance");
        require(msg.sender == owner, "test caller must be owner");

        c.burn(v);

        uint256 after = c.totalSupply();
        // General rule: after == before - v
        assert(after == before - v);
    }
    receive() external payable {}
}

