contract InvMutTest is Test {
    C c;
    address owner = address(1);

    function setUp() public { c = new C(0, 0, 0); }

    function testFuzz_property(uint256 burnAmount) public {
        // keep burnAmount within a wide admissible domain but allow zero
        burnAmount = bound(burnAmount, 0, type(uint256).max);

        // Make address(1) the msg.sender/owner for calls
        // fund owner so that if constructor set balances based on decimals it won't revert
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        // The contract was constructed with initialSupply 0, decimals 0, so owner's balance is 0.
        // To test burn behavior we need owner to have at least burnAmount tokens. Mint tokens to owner via mintToken (onlyOwner)
        vm.prank(owner);
        // mint a large amount so any reasonable burnAmount (bounded by uint256) that we choose is allowed
        c.mintToken(owner, type(uint256).max / 2);

        // record totalSupply before
        uint256 before = c.totalSupply();

        // owner performs burn; use prank so msg.sender == owner (owner has onlyOwner privilege)
        vm.prank(owner);
        // Call burn and ignore revert semantics: if it reverts, then the burn did not succeed and the invariant about successful burns holds vacuously.
        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful burn, the reference contract guarantees totalSupply decreases exactly by burnAmount.
        // We assert that if the burn succeeded then totalSupply == before - burnAmount.
        // This single assert reads c's public getter and will hold for the reference and be violated by the mutant for some burnAmount.
        if (ok) {
            uint256 after = c.totalSupply();
            assertTrue(after + burnAmount == before);
        } else {
            // If burn reverted, then totalSupply must be unchanged; assert that as well (still a single assertion overall because conditionally executed)
            uint256 after = c.totalSupply();
            assertTrue(after == before);
        }
    }
}

