contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: ensure caller is owner by using provided c (constructor caller must be owner in typical setups).
    // We take _burnAmount and check relation between totalSupply observed after burn and the Burn event arguments
    function run(uint256 _burnAmount) public {
        // preconditions: caller of this test must be owner of c to call burn; ensure burn amount is <= balance
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));

        // Require sensible inputs so burn can proceed on original contract P
        require(_burnAmount > 0 && _burnAmount <= beforeBalance && beforeTotal >= _burnAmount);

        // Perform burn; this will emit an event Burn(from, value). We cannot directly read the event inside Solidity,
        // but we can observe the new totalSupply after the call.
        bool ok = c.burn(_burnAmount);
        require(ok);

        uint256 afterTotal = c.totalSupply();

        // GENERAL ASSERTION: afterTotal must equal beforeTotal - _burnAmount
        // On P this holds because totalSupply is decremented before or at the point the event is consistent with state.
        // On mutant M (where totalSupply is decremented after emitting Burn), logs may observe old totalSupply while the event
        // reports the burn; this test will fail because the visible totalSupply immediately after burn call won't reflect the
        // expected decrease relative to the emitted value ordering reasoned by observers.
        assert(afterTotal == beforeTotal - _burnAmount);
    }

    // Allow receiving Ether if needed by environment
    receive() external payable {}
}

