contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // require that msg.sender is the owner stored in c and that owner has enough balance to burn v
        // We observe owner address via the public owner() getter
        address owner = c.owner();
        // precondition: this test contract must call burn as owner, so require the test caller is the owner
        require(msg.sender == owner);
        // also require owner has at least v balance
        require(c.balanceOf(owner) >= v);

        // perform the state-changing call as a top-level statement
        c.burn(v);

