// emits the Burn event before decrementing totalSupply, so such an observer can
// detect a mismatch: the emitted Burn.value equals amount but totalSupply still
// reports the old value. We implement a minimal observer contract whose
// fallback is triggered by the event emission (by making the observer the tx
// sender and reading totalSupply after the burn call) — to ensure the observer
// can read totalSupply after the call completes within the same tx we use a
// helper that calls burn and then calls back into the observer to read c.totalSupply().

contract InvMutTest is Test {
    C c;
    Helper helper;

    function setUp() public {
        // per instructions: deploy c using exact constructor args
        c = new C(0, 0, 0);
        helper = new Helper();
        // make helper the contract owner by transferring balance and then
        // making helper the owner is not possible externally; instead we use
        // vm.prank to have helper deployer semantics when calling burn.
        // For this contract C, constructor sets owner = msg.sender. setUp
        // was called by the test contract; test contract is owner.
        // We'll use vm.prank(address(this)) when calling burn to act as owner.
        // Ensure the test contract has a positive balance in c to burn from.
        // c was constructed with totalSupply = 0 (initialSupply 0), so mint some
        // tokens to address(this) to enable burning.
        vm.prank(address(this));
        c.mintToken(address(this), 1000);
    }

    // We fuzz the burn amount to let the fuzzer find a distinguishing amount.
    // Keep domain wide but constrained to available balance.
    function testFuzz_property(uint256 amount) public {
        // admissible domain: amount between 1 and current balance (1000)
        // keep it wide but necessary so burn succeeds in reference contract
        amount = bound(amount, 1, 1000);

        // We will perform the following steps in a single transaction from the
        // test contract (which is the owner): call burn(amount) on c, then read
        // c.totalSupply(). The reference guarantees totalSupply decreased by
        // amount after the call; the mutant can be detected because an
        // on-chain observer triggered by the Burn event could read the old
        // totalSupply. To simulate the observer reading in the same tx after
        // the event, we directly call burn and then immediately read totalSupply.

        uint256 before = c.totalSupply();

        // call burn as owner (test contract is owner)
        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
